import{_ as a,a as s,b as i}from"./chunks/workbench.CkAH1RwQ.js";import{_ as t,o,c as p,a2 as r}from"./chunks/framework.Ky-Ipuyb.js";const b=JSON.parse('{"title":"ImGui サンプル","description":"","frontmatter":{"lang":"ja","sourcePath":"packages/sfml.js-imgui/examples/README.ja.md"},"headers":[],"relativePath":"ja/examples/imgui.md","filePath":"ja/examples/imgui.md"}'),m={name:"ja/examples/imgui.md"};function n(c,e,l,d,g,h){return o(),p("div",null,[...e[0]||(e[0]=[r('<h1 id="imgui-サンプル" tabindex="-1">ImGui サンプル <a class="header-anchor" href="#imgui-サンプル" aria-label="Permalink to &quot;ImGui サンプル&quot;">​</a></h1><p>ネイティブの SFML ウィンドウで Dear ImGui のウィジェットを動かします。まずデモを試し、シーンパネルと Workbench で、編集した状態を SFML の描画に反映する方法を確認できます。</p><h2 id="実行前の準備" tabindex="-1">実行前の準備 <a class="header-anchor" href="#実行前の準備" aria-label="Permalink to &quot;実行前の準備&quot;">​</a></h2><p>以下のコマンドは <strong>monorepo のルート</strong>で実行します。初回に bootstrap で依存関係を導入し、各パッケージをビルドしてください。ディスプレイと OpenGL が必要です。<a href="/ja/guide/getting-started#requirements">プラットフォーム要件</a>も確認してください。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/bootstrap.cjs</span></span></code></pre></div><p>ImGui の TypeScript ソースを変更したら、<code>npm run build:ts --prefix packages/sfml.js-imgui</code> で再ビルドします。サンプルはローカルでビルドしたパッケージを使います。</p><h2 id="サンプル" tabindex="-1">サンプル <a class="header-anchor" href="#サンプル" aria-label="Permalink to &quot;サンプル&quot;">​</a></h2><div class="example-gallery"><article class="example-entry" id="demo"><a href="/media/imgui/examples/screenshots/demo.png"><img src="'+a+'" width="360" alt="Tables and Columns を展開した Dear ImGui デモ"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-imgui/examples/demo.cjs">demo.cjs</a></strong></p><p>Dear ImGui ウィジェットデモ</p><p><code>node packages/sfml.js-imgui/examples/demo.cjs</code></p><p><strong>操作</strong>：内蔵デモのウィジェット、レイアウト、テーブル、 グラフを展開します。別の sfml.js-imgui パネルにはフレーム数と Reset ボタンがあります。ウィンドウを閉じて終了します。 </p></div></article></div><article class="example-entry" id="scene-inspector"><a href="/media/imgui/examples/screenshots/scene-inspector.png"><img src="'+s+'" width="360" alt="シーンパネルの SFML の円と ImGui カラーピッカー"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-imgui/examples/scene-inspector.cjs">scene-inspector.cjs</a></strong></p><p>ImGui パネルから動く SFML の円を操作する</p><p><code>node packages/sfml.js-imgui/examples/scene-inspector.cjs</code></p><p><strong>操作</strong>：Animate、Speed、Radius、Color でシーンを編集し、 Reset scene で初期値へ戻します。パネルの外をクリックして Space を押すと、 操作中のウィジェットに影響せず停止・再開できます。 </p><p><a href="/ja/imgui/widgets">ウィジェットと状態</a></p></div></article><article class="example-entry" id="workbench"><a href="/media/imgui/examples/screenshots/workbench.png"><img src="'+i+'" width="360" alt="テキスト入力、選択、テーブル、グラフを含む ImGui Workbench"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-imgui/examples/workbench.cjs">workbench.cjs</a></strong></p><p>テキスト入力、コールバック、テーブル、モーダル、独自描画</p><p><code>node packages/sfml.js-imgui/examples/workbench.cjs</code></p><p><strong>操作</strong>：Name を編集し、オブジェクトを選択し、表の行を 切り替えます。Scene → Reset… で確認モーダルを開きます。 コマンドに TTF パスを追加するとラテン文字フォントを試せます。 </p><p><a href="/ja/imgui/layout">レイアウト</a> · <a href="/ja/imgui/callbacks">コールバック</a> · <a href="/ja/imgui/rendering">描画</a></p></div></article><p>3 つのサンプルはすべてのイベントを転送し、ウィンドウを折りたたんでも <code>Begin</code> と <code>End</code> を対応させ、型付き配列の状態をフレームループの外に保持し、SFML ウィンドウを閉じる前に ImGui を終了します。スクリーンショットは macOS で実際に動作しているネイティブサンプルから撮影しました。</p><p><a href="/ja/examples">全サンプル</a> · <a href="/ja/imgui/getting-started">ImGui クイックスタート</a></p>',12)])])}cons